const express = require("express");
const fs = require("fs");
const path = require("path");

const app = express();
const PORT = 3200;

const CLAUDE_MD_PATH = path.join(
  process.env.HOME,
  ".claude",
  "CLAUDE.md"
);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

// Parse CLAUDE.md into structured sections
function parseClaude(content) {
  const sections = [];
  const lines = content.split("\n");
  let current = null;

  for (const line of lines) {
    if (line.startsWith("## ")) {
      if (current) sections.push(current);
      current = { title: line.replace("## ", ""), rules: [], raw: "" };
    } else if (current) {
      current.raw += line + "\n";
      const trimmed = line.trim();
      if (trimmed.startsWith("- ") || trimmed.match(/^\d+\.\s/)) {
        current.rules.push(trimmed.replace(/^[-\d.]+\s*/, ""));
      }
    }
  }
  if (current) sections.push(current);
  return sections;
}

// Rebuild CLAUDE.md from structured data
function buildClaude(title, sections) {
  let md = `# ${title}\n\n`;
  for (const section of sections) {
    md += `## ${section.title}\n`;
    if (section.rules && section.rules.length > 0) {
      for (const rule of section.rules) {
        md += `- ${rule}\n`;
      }
    } else if (section.raw) {
      md += section.raw;
    }
    md += "\n";
  }
  return md;
}

// GET — read current rules
app.get("/api/rules", (req, res) => {
  try {
    const content = fs.readFileSync(CLAUDE_MD_PATH, "utf-8");
    const firstLine = content.split("\n")[0];
    const title = firstLine.replace("# ", "");
    const sections = parseClaude(content);
    res.json({ title, sections, raw: content });
  } catch (err) {
    res.status(500).json({ error: "Could not read CLAUDE.md" });
  }
});

// PUT — save full rules
app.put("/api/rules", (req, res) => {
  try {
    const { title, sections } = req.body;
    const content = buildClaude(title, sections);
    fs.writeFileSync(CLAUDE_MD_PATH, content, "utf-8");
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: "Could not write CLAUDE.md" });
  }
});

// PUT — save raw markdown directly
app.put("/api/rules/raw", (req, res) => {
  try {
    const { content } = req.body;
    fs.writeFileSync(CLAUDE_MD_PATH, content, "utf-8");
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: "Could not write CLAUDE.md" });
  }
});

// GET — list all project CLAUDE.md files
app.get("/api/projects", (req, res) => {
  try {
    const projectsDir = path.join(process.env.HOME, "projects");
    if (!fs.existsSync(projectsDir)) return res.json({ projects: [] });

    const dirs = fs.readdirSync(projectsDir, { withFileTypes: true });
    const projects = [];

    for (const dir of dirs) {
      if (!dir.isDirectory()) continue;
      const claudePath = path.join(projectsDir, dir.name, "CLAUDE.md");
      if (fs.existsSync(claudePath)) {
        const content = fs.readFileSync(claudePath, "utf-8");
        projects.push({ name: dir.name, path: claudePath, content });
      }
    }
    res.json({ projects });
  } catch (err) {
    res.status(500).json({ error: "Could not scan projects" });
  }
});

// PUT — save project CLAUDE.md
app.put("/api/projects/:name", (req, res) => {
  try {
    const { content } = req.body;
    const claudePath = path.join(
      process.env.HOME,
      "projects",
      req.params.name,
      "CLAUDE.md"
    );
    fs.writeFileSync(claudePath, content, "utf-8");
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: "Could not write project CLAUDE.md" });
  }
});

app.listen(PORT, () => {
  console.log(`\n  Claude Rules Manager running at:\n`);
  console.log(`  http://localhost:${PORT}\n`);
});

