app.put("/api/projects/:name", (req, res) => {
  try {
    const { content } = req.body;
    const claudePath = path.join(
      process.env.HOME,
      "projects",
      req.params.name,
      "CLAUDE.md"
    );
    fs.writeFileSync(claudePath, content, "utf-8");
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: "Could not write project CLAUDE.md" });
  }
});

app.listen(PORT, () => {
  console.log(`\n  Claude Rules Manager running at:\n`);
  console.log(`  http://localhost:${PORT}\n`);
});
